export const FOOD_ERAS: FoodItem[][] = DATA.eras;

/** The food table for one version. */
export function foodsFor(version: VersionId): FoodItem[] {
  return DATA.eras[DATA.versionEra[version]] ?? [];
}

/** Look up one food in one version, or undefined when it does not exist there. */
export function foodById(version: VersionId, id: string): FoodItem | undefined {
  return foodsFor(version).find((f) => f.id === id);
}

/**
 * Core hunger constants. Identical in every verified version.
 * Source: net.minecraft.world.food.FoodConstants and FoodData#tick.
 */
export const MECHANICS = {
  /** Hunger bar maximum, in points. Ten drumstick icons of 2 points each. */
  maxFood: 20,
  /** Saturation maximum; also clamped to the current food level on eating. */
  maxSaturation: 20,
  /** Saturation a freshly spawned player starts with. */
  startSaturation: 5,
  /** Exhaustion consumed to burn one saturation point, then one food point. */
  exhaustionDrop: 4,
  /** Exhaustion is clamped here, so a huge burst is partly discarded. */
  maxExhaustion: 40,
  /** Ticks between heals on the normal regeneration path. */
  healthTickCount: 80,
  /** Ticks between heals on the saturated fast path. */
  healthTickCountSaturated: 10,
  /** Food level at or above which normal regeneration runs. */
  healLevel: 18,
  /** Exhaustion added per health point healed on the normal path. */
  exhaustionHeal: 6,
  /** Saturation spent per fast heal is capped here. */
  saturatedHealCap: 6,
  /** Food level at or above which the player can sprint. */
  sprintLevel: 6,
  /** Food level at or below which starvation damage starts. */
  starveLevel: 0,
} as const;

export interface Activity {
  id: string;
  label: string;
  unit: string;
  unitPlural: string;
  /** Exhaustion per unit. */
  exhaustion: number;
  /** Class and method the number was read from. */
  source: string;
  /**
   * Versions where this action exists at all. Absent means every version.
   * Only the enchantment-driven costs are gated, and the panel hides them
   * outside those versions so no impossible combination is ever offered.
   */
  availableIn?: string[];
}

/** Every exhaustion source a player controls, with its per-unit cost. */
export const ACTIVITIES: readonly Activity[] = JSON.parse(
  '[{"id":"sprint","label":"Sprinting","unit":"block","unitPlural":"blocks","exhaustion":0.1,"source":"ServerPlayer#checkMovementStatistics (Player#checkMovementStatistics before 1.20): 0.1F per centimeter-hundredth, so 0.1 per block sprinted"},{"id":"swim","label":"Swimming","unit":"block","unitPlural":"blocks","exhaustion":0.01,"source":"ServerPlayer#checkMovementStatistics: 0.01F per block swum, walked underwater, or walked on water"},{"id":"walk","label":"Walking or crouching","unit":"block","unitPlural":"blocks","exhaustion":0,"source":"ServerPlayer#checkMovementStatistics: 0.0F per block walked or crouched, so plain walking is free"},{"id":"jump","label":"Jumping","unit":"jump","unitPlural":"jumps","exhaustion":0.05,"source":"ServerPlayer#jumpFromGround (Player#jumpFromGround before 1.21.2): 0.05F when not sprinting"},{"id":"sprint_jump","label":"Sprint jumping","unit":"jump","unitPlural":"jumps","exhaustion":0.2,"source":"ServerPlayer#jumpFromGround (Player#jumpFromGround before 1.21.2): 0.2F when sprinting"},{"id":"mine","label":"Breaking blocks","unit":"block","unitPlural":"blocks","exhaustion":0.005,"source":"Block#playerDestroy: 0.005F per block broken, whatever the block or tool"},{"id":"attack","label":"Attacking","unit":"hit landed","unitPlural":"hits landed","exhaustion":0.1,"source":"Player#attack: 0.1F per attack that deals damage; a miss or a fully blocked hit costs nothing"},{"id":"damage","label":"Taking damage","unit":"hit taken","unitPlural":"hits taken","exhaustion":0.1,"source":"Player#actuallyHurt via DamageSource#getFoodExhaustion: 0.1 for mob_attack, player_attack, arrow, explosion, cactus, thorns, fire and lava; 0.0 for fall, drowning, starving, magic, wither and freezing"},{"id":"hunger_effect","label":"Hunger effect","unit":"second","unitPlural":"seconds","exhaustion":0.1,"source":"HungerMobEffect#applyEffectTick (MobEffect#applyEffectTick before 1.20.5): 0.005F x (amplifier + 1) every tick, so 0.1 per second at Hunger I"},{"id":"ench_lunge","label":"Lunge attack","unit":"Lunge I attack","unitPlural":"Lunge I attacks","exhaustion":4,"source":"Enchantments.LUNGE carries the apply_exhaustion entity effect with a base of 4 exhaustion, scaling linearly with the level up to 3. Enter level times your attack rate for higher levels.","availableIn":["1.21.11","26.2"]}]',
) as Activity[];

export const ACTIVITY_BY_ID: ReadonlyMap<string, Activity> = new Map(
  ACTIVITIES.map((a) => [a.id, a]),
);

/** The actions that exist in one version. */
export function activitiesFor(version: VersionId): Activity[] {
  return ACTIVITIES.filter((a) => !a.availableIn || a.availableIn.includes(version));
}

export interface ActivityPreset {
  id: string;
  label: string;
  /** True when a rate assumes a measured travel speed rather than game code. */
  approximate: boolean;
  note: string;
  /** activity id -> units per minute. Missing activities are zero. */
  rates: Record<string, number>;
}

/**
 * Ready-made activity mixes. Every exhaustion cost per unit is source-derived;
 * the rates are not in the game code, because the game charges per block
 * traveled rather than per second. Presets that assume a travel speed are
 * flagged approximate and every rate stays editable.
 */
